pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, uint256 amount, uint256 previousBalance) public {
        vm.assume(amount <= type(uint256).max - previousBalance);
        vm.assume(previousBalance <= type(uint256).max / 2); // avoid overflow in deposit
        vm.deal(caller, amount + previousBalance);
        vm.prank(caller);

        // Set initial balance by calling deposit with previousBalance
        if (previousBalance > 0) {
            c.deposit{value: previousBalance}();
        }

        uint256 balanceBefore = address(caller).balance;
        (bool success, ) = address(c).call{value: amount}(abi.encodeWithSignature("deposit()"));
        uint256 balanceAfter = address(caller).balance;

        assertTrue(success == true && balanceAfter == balanceBefore - amount, "deposit should succeed and decrement caller's balance by amount");
    }
}

