pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address sender, uint256 initialBalance, uint256 depositAmount) public {
        vm.assume(initialBalance <= type(uint256).max - depositAmount);
        vm.assume(depositAmount > 0);

        // Set up initial balance for sender
        if (sender != address(0)) {
            vm.prank(sender);
            (bool success, ) = address(c).call{value: initialBalance}(abi.encodeWithSignature("deposit()"));
            if (success) {
                // Already deposited once, just continue
            } else {
                // Use refund to get initial balance
                vm.prank(sender);
                c.refund();
                vm.deal(sender, initialBalance);
                vm.prank(sender);
                c.deposit{value: initialBalance}();
            }
        } else {
            vm.deal(sender, initialBalance);
            vm.prank(sender);
            c.deposit{value: initialBalance}();
        }

        // Now test: deposit with amount that would overflow
        vm.deal(sender, depositAmount);
        vm.prank(sender);
        try c.deposit{value: depositAmount}() {
            // deposit succeeded - this should only happen if no overflow
            assertTrue(initialBalance + depositAmount >= initialBalance);
        } catch {
            // deposit reverted - should happen only when overflow would occur
            assertTrue(initialBalance + depositAmount < initialBalance);
        }
    }
}

