pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller1, address caller2, uint256 amount1, uint256 amount2) public {
        vm.assume(caller1 != address(0) && caller2 != address(0));
        vm.assume(amount1 <= 1e24 && amount2 <= 1e24);

        // Perform some deposits to accumulate balances
        vm.deal(caller1, amount1);
        vm.prank(caller1);
        c.deposit{value: amount1}();

        vm.deal(caller2, amount2);
        vm.prank(caller2);
        c.deposit{value: amount2}();

        // The invariant: total ether in system (contract balance + caller1's balance + caller2's balance) 
        // should equal the total deposited (amount1 + amount2) minus any withdrawals
        uint256 contractBal = address(c).balance;
        uint256 caller1Bal = c.balances(caller1);
        uint256 caller2Bal = c.balances(caller2);

        // Since we only deposited, sum of balances should equal total deposited (but no overflow check may corrupt)
        uint256 sumBalances = caller1Bal + caller2Bal;
        uint256 totalDeposited = amount1 + amount2;

        // The invariant: contract balance + all user balances = total deposited
        assertTrue(contractBal + sumBalances == totalDeposited, "Invariant violated: total ether mismatch");
    }
}

