pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address addr1, address addr2, uint256 amount1, uint256 amount2) public {
        // Bound amounts to prevent overflow in deposit (the original contract requires this)
        vm.assume(amount1 <= type(uint256).max - 1e18);
        vm.assume(amount2 <= type(uint256).max - 1e18);

        // Ensure addresses are distinct and not zero
        vm.assume(addr1 != address(0) && addr2 != address(0) && addr1 != addr2);

        // Deal ether to both addresses
        vm.deal(addr1, amount1);
        vm.deal(addr2, amount2);

        // Capture total balance before: sum of all user balances (only those we can observe via public getter) plus contract balance
        uint256 totalBefore = c.balances(addr1) + c.balances(addr2) + address(c).balance;

        // Perform a deposit from addr1
        vm.prank(addr1);
        (bool success1, ) = address(c).call{value: 1 ether}("");
        if (!success1) return; // skip if revert

        // Perform a deposit from addr2
        vm.prank(addr2);
        (bool success2, ) = address(c).call{value: 1 ether}("");
        if (!success2) return;

        // Capture total balance after
        uint256 totalAfter = c.balances(addr1) + c.balances(addr2) + address(c).balance;

        // General rule: total balance (sum of observable balances + contract balance) never decreases
        assertTrue(totalAfter >= totalBefore, "Total balance decreased");
    }
}

